<?php
if (session_status() === PHP_SESSION_NONE) { session_start(); }
if (!in_array(trim((string)($_SESSION['usertype'] ?? '')), ['Host', 'Trainer'], true)) { header('Location: index.php'); exit; }
if (empty($_SESSION['csrf_token'])) { $_SESSION['csrf_token'] = bin2hex(random_bytes(32)); }
require_once __DIR__ . '/dbConnection_PDO.php';
$hostId = (int)($_SESSION['user_id'] ?? 0); $playerId = (int)($_GET['id'] ?? 0); $tournamentId = (int)($_GET['tournament_id'] ?? 0);
$teamStmt = $pdo->prepare('SELECT t.* FROM to_users u JOIN to_teams t ON u.TEAM_ID = t.ID JOIN to_tournaments tr ON t.TOURNAMENT_ID = tr.ID WHERE u.ID = ? AND tr.ID = ? AND tr.HOST_ID = ? LIMIT 1');
$teamStmt->execute([$playerId, $tournamentId, $hostId]); $team = $teamStmt->fetch(PDO::FETCH_ASSOC);
if (!$team) { http_response_code(403); exit('Registration not found or access denied.'); }
$playersStmt = $pdo->prepare('SELECT * FROM to_users WHERE TEAM_ID = ? ORDER BY ID ASC'); $playersStmt->execute([(int)$team['ID']]); $players = $playersStmt->fetchAll(PDO::FETCH_ASSOC);
include 'includes/inner-header.php';
?>
<link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet">
<main class="container py-5" style="max-width:1100px"><div class="d-flex justify-content-between align-items-center mb-4"><h2 class="mb-0">Edit Team Registration</h2><a class="btn btn-outline-secondary" href="host-enrolled-tournaments.php?tournament_id=<?php echo $tournamentId; ?>">Back to enrolled users</a></div><form id="editRegForm" class="card shadow-sm"><div class="card-body p-4"><input type="hidden" name="team_id" value="<?php echo (int)$team['ID']; ?>"><input type="hidden" name="tournament_id" value="<?php echo $tournamentId; ?>"><div class="row mb-4"><label class="col-md-3 col-form-label fw-bold">Team Name</label><div class="col-md-7"><input class="form-control" name="team_name" required value="<?php echo htmlspecialchars($team['NAME'],ENT_QUOTES,'UTF-8'); ?>"></div></div><hr><div class="row"><?php foreach($players as $i=>$p): ?><div class="col-md-<?php echo count($players)>1?'6':'12'; ?> p-3"><h5 class="text-primary">Player <?php echo $i+1; ?> Details</h5><div class="mb-2"><label>Full Name</label><input class="form-control" name="players[<?php echo (int)$p['ID']; ?>][name]" required value="<?php echo htmlspecialchars($p['NAME'],ENT_QUOTES,'UTF-8'); ?>"></div><div class="mb-2"><label>Contact</label><input class="form-control" name="players[<?php echo (int)$p['ID']; ?>][whatsapp]" value="<?php echo htmlspecialchars($p['WHATSAPP_NUMBER'],ENT_QUOTES,'UTF-8'); ?>"></div><div class="mb-2"><label>Email</label><input type="email" class="form-control" name="players[<?php echo (int)$p['ID']; ?>][email]" required value="<?php echo htmlspecialchars($p['EMAIL'],ENT_QUOTES,'UTF-8'); ?>"></div><div class="mb-2"><label>DOB</label><input type="date" class="form-control" name="players[<?php echo (int)$p['ID']; ?>][dob]" value="<?php echo htmlspecialchars($p['DOB'] ?? '',ENT_QUOTES,'UTF-8'); ?>"></div><div class="mb-2"><label>Gender</label><select class="form-select" name="players[<?php echo (int)$p['ID']; ?>][gender]"><option <?php echo $p['GENDER']==='Male'?'selected':''; ?>>Male</option><option <?php echo $p['GENDER']==='Female'?'selected':''; ?>>Female</option></select></div><div class="mb-2"><label>City</label><input class="form-control" name="players[<?php echo (int)$p['ID']; ?>][city]" value="<?php echo htmlspecialchars($p['CITY'],ENT_QUOTES,'UTF-8'); ?>"></div><label><input type="checkbox" name="players[<?php echo (int)$p['ID']; ?>][exist]" value="Y" <?php echo ($p['EXISTING'] ?? '')==='Y'?'checked':''; ?>> Existing Member</label></div><?php endforeach; ?></div></div><div class="card-footer text-end"><button class="btn btn-primary" id="saveButton">Update Entire Team</button></div></form></main>
<script src="https://code.jquery.com/jquery-3.7.1.min.js"></script><script>$('#editRegForm').on('submit',function(e){e.preventDefault();const b=$('#saveButton').prop('disabled',true).text('Updating...');$.ajax({url:'api/host_sync_player.php',type:'POST',dataType:'json',data:$(this).serialize()+'&action=update_team&csrf_token=<?php echo $_SESSION['csrf_token']; ?>'}).done(r=>r.success?location.href='host-enrolled-tournaments.php?tournament_id=<?php echo $tournamentId; ?>':(alert(r.message),b.prop('disabled',false).text('Update Entire Team'))).fail(()=>{alert('Connection error occurred.');b.prop('disabled',false).text('Update Entire Team');});});</script>
